ALTER TABLE student_accounts ADD COLUMN IF NOT EXISTS session_version INT NOT NULL DEFAULT 1;
ALTER TABLE student_requests ADD COLUMN IF NOT EXISTS response TEXT NULL;
ALTER TABLE student_requests ADD COLUMN IF NOT EXISTS updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP;
CREATE TABLE IF NOT EXISTS student_request_updates(id BIGINT AUTO_INCREMENT PRIMARY KEY,request_id BIGINT NOT NULL,status VARCHAR(30) NOT NULL,response TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
